# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps

OPEN = Span(8 * 60, 18 * 60)

class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = [Span(480, 720), Span(780, 1080)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        worked = [Span(600, 900)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            [
                "gap 08:00-10:00 (120 min)",
                "gap 15:00-18:00 (180 min)"
            ]
        )

    def test_nobody_working(self):
        self.assertEqual(
            find_gaps([], OPEN),
            ["gap 08:00-18:00 (600 min)"]
        )

    def test_full_coverage_has_no_gaps(self):
        worked = [Span(480, 800), Span(700, 1080)]
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_overlapping_workers_count_once(self):
        worked = [Span(480, 700), Span(600, 720)]
        self.assertEqual(
            find_gaps(worked, Span(480, 780)),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(420, 600)], OPEN)

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(600, 1100)], OPEN)
